// Evaluate retrieved chunks against the configurable similarity thresholds and
// build the grounded context that is later injected into the LLM prompt.
const envelope = $('When Called by Another Workflow').first().json;
const hits = $('Postgres Vector Store').all().map(i => i.json);

const strongThreshold = Number(process.env.RAG_STRONG_THRESHOLD || 0.5);
const similarityThreshold = Number(process.env.RAG_SIMILARITY_THRESHOLD || 0.3);
const topK = Number(process.env.RAG_TOP_K || 4);

function toNumber(v) {
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) ? n : 0;
}

function parseMetadata(m) {
  if (m && typeof m === 'object') return m;
  if (typeof m === 'string') {
    try { return JSON.parse(m); } catch (e) { return {}; }
  }
  return {};
}

// The vector store load operation returns { document: { pageContent, metadata }, score }.
// score is the cosine distance (0 = identical, higher = worse), so convert it to a
// similarity in [0,1] where higher is better.
const normalized = hits
  .map(h => {
    const doc = h.document || {};
    const distance = toNumber(h.score);
    const similarity = Math.max(0, Math.min(1, 1 - distance));
    return {
      chunk_text: String(doc.pageContent || ''),
      metadata: parseMetadata(doc.metadata),
      score: similarity,
      distance
    };
  })
  .filter(h => h.chunk_text.trim())
  .sort((a, b) => b.score - a.score);

const bestScore = normalized.length ? normalized[0].score : 0;
const strong = normalized.length > 0 && bestScore >= strongThreshold;
const weak = !strong && normalized.length > 0 && bestScore >= similarityThreshold;
const miss = normalized.length === 0 || bestScore < similarityThreshold;

const top_context = normalized.slice(0, topK)
  .map(h => `[Title: ${h.metadata.title || h.metadata.document_id || 'unknown'}] [Category: ${h.metadata.category || 'general'}]
${h.chunk_text}`)
  .join('\n\n---\n\n');

const rag = {
  query: envelope.message,
  hits: normalized,
  best_score: bestScore,
  strong,
  weak,
  miss,
  top_context
};

return [{ json: { ...envelope, rag } }];
